"""Pratt parser for the executable subset of jq used by the interpreter."""
from __future__ import annotations

from dataclasses import dataclass
from .diagnostics import CompileError
from .lexer import tokenize


@dataclass(frozen=True)
class Filter:
    kind: str
    value: object = None
    children: tuple["Filter", ...] = ()


class Parser:
    # Lower number binds less tightly.  jq's comma is a generator, not an
    # argument separator; semicolons are the argument separators.
    PRECEDENCE = {"=": 0, "|=": 0, "+=": 0, "-=": 0, "*=": 0, "/=": 0,
                  "%=": 0, "//=": 0, "|": 1, ",": 2, "//": 3,
                  "or": 4, "and": 5, "==": 6, "!=": 6, "<": 6,
                  ">": 6, "<=": 6, ">=": 6, "+": 7, "-": 7,
                  "*": 8, "/": 8, "%": 8}

    def __init__(self, source: str) -> None:
        self.source = source
        # A binding is a compile-time name, not a dynamic lookup.  Keeping the
        # names here lets the parser distinguish an unbound `$name` (jq's
        # static error) from a binding introduced by `as`.
        self.bound_names: set[str] = set()
        self.function_names: set[tuple[str, int]] = set()
        self.parameter_names: set[str] = set()
        keyword = {"as", "if", "then", "else", "elif", "end", "or", "and", "catch"}
        self.tokens = [((str(t.value) if t.kind == "IDENT" and t.value in keyword else
                         {"NUMBER":"num", "STRING":"str", "IDENT":"id", "FIELD":"field", "BINDING":"binding", "FORMAT":"format"}.get(t.kind, t.kind)), t.value, t.position)
                       for t in tokenize(source)]
        self.pos = 0

    def peek(self, *k: str) -> bool:
        return self.tokens[self.pos][0] in k

    def pop(self, expected: str | None = None) -> tuple[str, object, int]:
        token = self.tokens[self.pos]
        if expected is not None and token[0] != expected:
            raise CompileError(f"expected {expected} at position {token[2]}")
        self.pos += 1
        return token

    def parse(self) -> Filter:
        if self.peek("EOF"):
            raise CompileError("empty filter")
        result = self.query()
        if not self.peek("EOF"):
            raise CompileError(f"unexpected token at position {self.tokens[self.pos][2]}")
        return result

    def query(self) -> Filter:
        # Definitions are expressions in jq: a definition installs a lexical
        # function and the expression after its semicolon is its continuation.
        if self.peek("id") and self.tokens[self.pos][1] == "def":
            self.pop()
            name = str(self.pop("id")[1])
            params: list[tuple[str, str]] = []
            if self.peek("("):
                self.pop()
                if not self.peek(")"):
                    while True:
                        kind, value, _ = self.pop()
                        if kind not in {"id", "binding"}:
                            raise CompileError("expected function parameter")
                        params.append(("value" if kind == "binding" else "filter", str(value)))
                        if not self.peek(";"): break
                        self.pop()
                self.pop(")")
            self.pop(":")
            signature = (name, len(params))
            self.function_names.add(signature)  # permits recursion
            old_params = self.parameter_names
            self.parameter_names = old_params | {p[1] for p in params}
            try:
                body = self.query()
            finally:
                self.parameter_names = old_params
            self.pop(";")
            continuation = self.query()
            return Filter("def", (name, tuple(params)), (body, continuation))
        # Binding is deliberately parsed below pipe precedence: `x as $y | f`.
        left = self.expr(0)
        if self.peek("as"):
            self.pop()
            pat = self.pattern()
            patterns = [pat]
            while self.peek("?//"):
                self.pop(); patterns.append(self.pattern())
            pat = patterns[0] if len(patterns) == 1 else Filter("pattern_alt", children=tuple(patterns))
            self.pop("|")
            previous = self.bound_names
            self.bound_names = previous | self._pattern_names(pat)
            try:
                body = self.query()
            finally:
                self.bound_names = previous
            return Filter("as", None, (left, pat, body))
        return left

    def _pattern_names(self, pattern: Filter) -> set[str]:
        if pattern.kind == "pattern":
            return {str(pattern.value)}
        if pattern.kind in {"array_pattern", "object_pattern"}:
            values: set[str] = set()
            children = pattern.children if pattern.kind == "array_pattern" else tuple(
                child for _, child in pattern.value
            )
            for child in children:
                values.update(self._pattern_names(child))
            return values
        if pattern.kind == "pattern_alt":
            values: set[str] = set()
            for child in pattern.children:
                values.update(self._pattern_names(child))
            return values
        return set()

    def expr(self, minimum: int) -> Filter:
        left = self.primary()
        while True:
            op = self.tokens[self.pos][0]
            if op not in self.PRECEDENCE or self.PRECEDENCE[op] < minimum:
                break
            precedence = self.PRECEDENCE[op]
            self.pop()
            # assignment and // are right associative; arithmetic is left.
            right = self.expr(precedence if op in {"=", "|=", "+=", "-=", "*=", "/=", "%=", "//=", "//"} else precedence + 1)
            left = Filter("binary", op, (left, right))
        return left

    def pattern(self) -> Filter:
        if self.peek("binding"):
            return Filter("pattern", self.pop()[1])
        if self.peek("["):
            self.pop(); items = []
            if not self.peek("]"):
                while True:
                    items.append(self.pattern())
                    if not self.peek(","): break
                    self.pop()
            self.pop("]"); return Filter("array_pattern", children=tuple(items))
        if self.peek("{"):
            self.pop(); items = []
            while not self.peek("}"):
                key_kind, key_value, _ = self.pop()
                if key_kind == "binding" and self.peek(",", "}"):
                    items.append((str(key_value), Filter("pattern", key_value)))
                else:
                    if key_kind == "binding":
                        key = str(key_value)
                    else:
                        key = str(key_value)
                    self.pop(":"); items.append((key, self.pattern()))
                if not self.peek(","): break
                self.pop()
            self.pop("}"); return Filter("object_pattern", items)
        raise CompileError(f"expected binding at position {self.tokens[self.pos][2]}")

    def primary(self) -> Filter:
        kind, value, position = self.pop()
        if kind == "EOF": raise CompileError("expected filter")
        if kind == "num" or kind == "str":
            node = Filter("template", value) if isinstance(value, list) else Filter("literal", value)
        elif kind == "field":
            node = Filter("field", value, (Filter("identity"),))
        elif kind == ".":
            node = Filter("identity")
        elif kind == "binding":
            if str(value) in self.bound_names:
                node = Filter("binding", value)
            elif str(value) in self.parameter_names:
                node = Filter("param", "@" + str(value))
            else:
                raise CompileError(f"variable is not defined at position {position}")
        elif kind == "-":
            node = Filter("unary", "-", (self.primary(),))
        elif kind == "(":
            node = self.query(); self.pop(")")
        elif kind == "[":
            parts = []
            if not self.peek("]"):
                parts.append(self.query())
            self.pop("]"); node = Filter("array", children=tuple(parts))
        elif kind == "{":
            pairs = []
            while not self.peek("}"):
                key = self.pop()
                if key[0] == "(" : key_filter = self.query(); self.pop(")")
                else: key_filter = Filter("literal", str(key[1]))
                self.pop(":"); pairs.append((key_filter, self.expr(3)))
                if not self.peek(","): break
                self.pop()
            self.pop("}"); node = Filter("object", tuple(pairs))
        elif kind in {"id", "if"}:
            if value in {"true", "false", "null"}: node = Filter("literal", {"true": True, "false": False, "null": None}[value])
            elif value == "empty": node = Filter("empty")
            elif value == "if":
                cond = self.query(); self.pop("then"); yes = self.query()
                no = Filter("literal", None)
                if self.peek("elif"):
                    self.pop(); no = self.primary()
                elif self.peek("else"):
                    self.pop(); no = self.query()
                self.pop("end"); node = Filter("if", children=(cond, yes, no))
            elif value == "try":
                attempt = self.primary() if not self.peek("(") else self.primary()
                handler = Filter("empty")
                if self.peek("catch"):
                    self.pop(); handler = self.query()
                node = Filter("try", children=(attempt, handler))
            elif value == "def":
                name = str(self.pop("id")[1]); params = []
                if self.peek("("):
                    self.pop()
                    if not self.peek(")"):
                        while True:
                            pk, pv, _ = self.pop(); params.append(("value" if pk == "binding" else "filter", str(pv)))
                            if not self.peek(";"): break
                            self.pop()
                    self.pop(")")
                self.pop(":"); self.function_names.add((name, len(params)))
                old_params = self.parameter_names; self.parameter_names = old_params | {p[1] for p in params}
                try: body = self.query()
                finally: self.parameter_names = old_params
                self.pop(";"); continuation = self.query()
                node = Filter("def", (name, tuple(params)), (body, continuation))
            else: node = self.call_or_builtin(str(value), position)
        elif kind == "format": node = Filter("format", value, (Filter("identity"),))
        else: raise CompileError(f"expected filter at position {position}")
        return self.postfix(node)

    def call_or_builtin(self, name: str, position: int) -> Filter:
        builtins = {"error","length","utf8bytelength","keys","values","type","add","any","all","flatten","sort","unique","reverse","min","max","floor","ceil","abs","not","arrays","objects","iterables","scalars","booleans","nulls","strings","numbers","tojson","fromjson","tostring","tonumber","sqrt","infinite","nan","try","range","map","map_values","contains","select","join","split","startswith","endswith","ltrimstr","rtrimstr","trimstr","getpath","setpath","delpaths","pow","log2","round","reduce","foreach"}
        if name in self.parameter_names and not self.peek("("):
            return Filter("param", "@" + name)
        if not self.peek("("):
            if name not in builtins and (name, 0) not in self.function_names:
                raise CompileError(f"unknown filter at position {position}")
            return Filter("call", name, ())
        self.pop("("); args = []
        if not self.peek(")"):
            while True:
                args.append(self.query())
                if not self.peek(";"): break
                self.pop(";")
        self.pop(")")
        if (name, len(args)) not in self.function_names and name not in builtins:
            raise CompileError(f"unknown function {name}/{len(args)}")
        return Filter("call", name, tuple(args))

    def postfix(self, node: Filter) -> Filter:
        while True:
            if self.peek("field"):
                node = Filter("field", self.pop()[1], (node,))
"""Ordered, generator-based jq evaluation."""
from __future__ import annotations
import base64, json, math, re, urllib.parse
from collections.abc import Iterator
from .data_model import JsonValue, is_truthy
from .diagnostics import RuntimeJqError
from .parser import Filter

def _walk(v):
    yield v
    if isinstance(v,dict):
        for x in v.values(): yield from _walk(x)
    elif isinstance(v,list):
        for x in v: yield from _walk(x)

def _num(x):
    if isinstance(x,bool) or not isinstance(x,(int,float)): raise RuntimeJqError('number required')
    return x

def _call(name,args,inp,env):
    functions = env.get("__funcs__", {})
    function = functions.get((name, len(args)))
    if function is not None:
        params, body, captured_env, captured_funcs = function
        local = dict(captured_env)
        local["__funcs__"] = captured_funcs
        # Filter parameters remain AST callbacks. Value parameters evaluate
        # once at the call site, matching jq's `$arg` parameter form.
        for (kind, param), argument in zip(params, args):
            if kind == "filter":
                local["@" + param] = ("filter", argument, env)
            else:
                local["@" + param] = ("filter", argument, env)
        yield from ev(body, inp, local)
        return
    if name=='map' and args:
        yield [z for x in inp for z in ev(args[0],x,env)]
        return
    if name=='map_values' and args:
        yield [next(ev(args[0],x,env),None) for x in inp] if isinstance(inp,list) else next(ev(args[0],inp,env))
        return
    vals=[list(ev(a,inp,env)) for a in args]
    def one(i=0): return vals[i][0] if vals and vals[i] else inp
    if name=='range':
        a=_num(one()); b=_num(vals[1][0]) if len(vals)>1 else a; step=_num(vals[2][0]) if len(vals)>2 else 1
        if len(vals)==1: a,b=0,a
        if step==0: raise RuntimeJqError('range step cannot be zero')
        x=a
        while (step>0 and x<b) or (step<0 and x>b): yield x; x+=step
    elif name in ('length','utf8bytelength'):
        yield len(one()) if not isinstance(one(),(int,float)) else abs(one())
    elif name=='type': yield 'null' if one() is None else ('boolean' if isinstance(one(),bool) else 'number' if isinstance(one(),(int,float)) else 'string' if isinstance(one(),str) else 'array' if isinstance(one(),list) else 'object')
    elif name=='keys': yield list(range(len(one()))) if isinstance(one(),list) else sorted(one().keys())
    elif name=='values':
        if one() is not None: yield one()
    elif name in ('tonumber','tostring','tojson','fromjson'):
        x=one()
        if name=='tonumber': yield float(x) if '.' in str(x) else int(x)
        elif name=='tostring': yield x if isinstance(x,str) else json.dumps(x,separators=(',',':'))
        elif name=='tojson': yield json.dumps(x,ensure_ascii=False,separators=(',',':'))
        else: yield json.loads(x)
    elif name in ('add','any','all','flatten','sort','unique','reverse','min','max'):
        x=one()
        if name=='add': yield sum(x) if x and all(isinstance(a,(int,float)) for a in x) else ''.join(x)
        elif name=='any': yield any(is_truthy(a) for a in x)
        elif name=='all': yield all(is_truthy(a) for a in x)
        elif name=='flatten':
            def flat(a):
                for q in a: yield from flat(q) if isinstance(q,list) else (q,)
            yield list(flat(x))
        elif name in ('sort','unique'): yield sorted(set(x)) if name=='unique' else sorted(x)
        elif name=='reverse': yield x[::-1]
        else: yield (min if name=='min' else max)(x)
    elif name=='contains': yield _contains(one(),vals[1][0])
    elif name=='startswith': yield one().startswith(vals[1][0])
    elif name=='endswith': yield one().endswith(vals[1][0])
    elif name=='floor': yield math.floor(_num(one()))
    elif name=='ceil': yield math.ceil(_num(one()))
    elif name=='abs': yield abs(_num(one()))
    elif name=='sqrt': yield math.sqrt(_num(inp))
    elif name=='not': yield not is_truthy(inp)
    elif name in ('arrays','objects','iterables','scalars','booleans','nulls','strings','numbers'):
        ok={'arrays':isinstance(inp,list),'objects':isinstance(inp,dict),'iterables':isinstance(inp,(list,dict)),'scalars':not isinstance(inp,(list,dict)),'booleans':isinstance(inp,bool),'nulls':inp is None,'strings':isinstance(inp,str),'numbers':isinstance(inp,(int,float)) and not isinstance(inp,bool)}[name]
        if ok: yield inp
    elif name=='join': yield (vals[0][0] if vals else '').join('' if x is None else str(x).lower() if isinstance(x,bool) else str(x) for x in inp)
    elif name=='split': yield one().split(vals[1][0])
    elif name in ('ltrimstr','rtrimstr','trimstr'):
        q=one(); x=inp
        if name=='ltrimstr': yield x[len(q):] if x.startswith(q) else x
        elif name=='rtrimstr': yield x[:-len(q)] if q and x.endswith(q) else x
        else: yield x[len(q):] if x.startswith(q) else x[:-len(q)] if q and x.endswith(q) else x
    elif name=='range': return
    elif name=='error': raise RuntimeJqError(str(one()) if args else 'error')
    elif name in ('in','inside'): yield False
    else: raise RuntimeJqError('unknown function '+name)

def _contains(a,b):
    if isinstance(a,str) and isinstance(b,str): return b in a
    if isinstance(a,list) and isinstance(b,list): return all(x in a for x in b)
    if isinstance(a,dict) and isinstance(b,dict): return all(k in a and _contains(a[k],v) for k,v in b.items())
    return a==b

def ev(f:Filter, inp:JsonValue, env:dict[str,JsonValue]|None=None)->Iterator[JsonValue]:
    env={} if env is None else env
    if "__funcs__" not in env:
        env = dict(env); env["__funcs__"] = {}
    k=f.kind
    if k=='identity': yield inp
    elif k=='literal': yield f.value
    elif k=='template':
        pieces = []
        for kind, value in f.value:
            if kind == 'text': pieces.append(value)
            else:
                from .parser import parse
                pieces.extend(str(x) if not isinstance(x, str) else x for x in ev(parse(value), inp, env))
        yield ''.join(pieces)
    elif k=='empty': return
    elif k=='error': raise RuntimeJqError('error')
    elif k == 'binding':
        if f.value not in env: raise RuntimeJqError(f"no such variable: ${f.value}")
        yield env[f.value]
    elif k == 'param':
        value = env.get(f.value)
        if isinstance(value, tuple) and value and value[0] == "filter":
            yield from ev(value[1], inp, value[2])
        else:
            yield value
    elif k=='comma':
        for c in f.children: yield from ev(c,inp,env)
    elif k=='field':
        for x in ev(f.children[0],inp,env):
            if isinstance(x,dict): yield x.get(f.value)
            else: raise RuntimeJqError('cannot index')
    elif k=='iterate':
        for x in ev(f.value[0],inp,env):
            if isinstance(x,(list,dict)): yield from (x if isinstance(x,list) else x.values())
            else: raise RuntimeJqError('cannot iterate')
    elif k in ('index','slice'):
        base,a,b=f.value
        for x in ev(base,inp,env):
            for ix in ev(a, x, env):
                if k=='index':
                    try: yield x[ix]
                    except (KeyError, IndexError, TypeError): raise RuntimeJqError('cannot index')
                else:
                    lo=ix; hi=None if b is None else next(ev(b,x,env),None); yield x[lo:hi]
    elif k=='array': yield [z for c in f.children for z in ev(c,inp,env)]
    elif k=='object':
        out={}
        for key,c in f.value:
            keys = list(ev(key, inp, env))
            vals = list(ev(c, inp, env))
            for actual_key in keys:
                out[str(actual_key)] = vals[-1] if vals else None
        yield out
    elif k == 'optional':
        try: yield from ev(f.children[0], inp, env)
        except RuntimeJqError: return
    elif k == 'try':
        try:
            yield from ev(f.children[0], inp, env)
        except RuntimeJqError as error:
            if f.children[1].kind != 'empty':
                yield from ev(f.children[1], str(error), env)
    elif k == 'if':
        cond, yes, no = f.children
        for value in ev(cond, inp, env):
            yield from ev(yes if is_truthy(value) else no, inp, env)
    elif k == 'as':
        source, pattern, body = f.children
        for value in ev(source, inp, env):
            local = dict(env)
            if pattern.kind == "pattern_alt":
                last_error = None
                all_names = set().union(*(_pattern_names(candidate) for candidate in pattern.children))
                for candidate in pattern.children:
                    attempt = dict(env)
                    for variable in all_names:
                        attempt[variable] = None
                    try:
                        _bind(candidate, value, attempt)
                        yield from ev(body, inp, attempt)
                        last_error = None
                        break
                    except RuntimeJqError as exc:
                        last_error = exc
                if last_error is not None:
                    raise last_error
            else:
                _bind(pattern, value, local)
                yield from ev(body, inp, local)
    elif k == 'def':
        (name, params), (body, continuation) = f.value, f.children
        functions = dict(env.get("__funcs__", {}))
        captured = dict(env)
        captured["__funcs__"] = functions
        functions[(name, len(params))] = (params, body, captured, functions)
        local = dict(env); local["__funcs__"] = functions
        yield from ev(continuation, inp, local)
    elif k=='unary':
        for x in ev(f.children[0],inp,env): yield -_num(x)
    elif k=='call': yield from _call(str(f.value),f.children,inp,env)
    elif k=='binary':
        op=f.value; l,r=f.children
        if op=='|':
            for x in ev(l,inp,env): yield from ev(r,x,env)
        elif op==',': yield from ev(l,inp,env); yield from ev(r,inp,env)
        elif op in ('=', '|=', '+=', '-=', '*=', '/=', '%=', '//='):
            yield from _update(l, r, op, inp, env)
        else:
            for a in ev(l,inp,env):
                for b in ev(r,inp,env): yield _binary(op,a,b)
    elif k=='recurse': yield from _walk(inp)
    else: raise RuntimeJqError('unsupported filter')

def _binary(op,a,b):
    if op=='//': return a if is_truthy(a) else b
    if op == 'and': return is_truthy(a) and is_truthy(b)
    if op == 'or': return is_truthy(a) or is_truthy(b)
    if op in ('==','!=','<','>','<=','>='): return {'==':a==b,'!=':a!=b,'<':a<b,'>':a>b,'<=':a<=b,'>=':a>=b}[op]
    if op=='+':
        if isinstance(a,dict) and isinstance(b,dict): return {**a,**b}
        if isinstance(a,list) and isinstance(b,list): return a+b
        return a+b
    if op=='-': return a-b if isinstance(a,(int,float)) else [x for x in a if x not in b]
    if op=='*': return a*b
    if op=='/': return a/b if not isinstance(a,str) else a.split(b)
    if op=='%': return a%b
    raise RuntimeJqError('unsupported operator')


def _bind(pattern: Filter, value: JsonValue, env: dict[str, JsonValue]) -> None:
    if pattern.kind == 'pattern':
        env[str(pattern.value)] = value
    elif pattern.kind == 'array_pattern':
        if not isinstance(value, list): raise RuntimeJqError('cannot destructure')
        for index, child in enumerate(pattern.children):
            _bind(child, value[index] if index < len(value) else None, env)
    elif pattern.kind == 'object_pattern':
        if not isinstance(value, dict): raise RuntimeJqError('cannot destructure')
        for key, child in pattern.value:
            _bind(child, value.get(key), env)
    elif pattern.kind == 'pattern_alt':
        _bind(pattern.children[0], value, env)


def _pattern_names(pattern: Filter) -> set[str]:
    if pattern.kind == "pattern":
        return {str(pattern.value)}
    if pattern.kind == "array_pattern":
        result: set[str] = set()
        for child in pattern.children:
            result.update(_pattern_names(child))
        return result
    if pattern.kind == "object_pattern":
        result = set()
        for _, child in pattern.value:
            result.update(_pattern_names(child))
        return result
    return set()


def _update(path: Filter, rhs: Filter, op: str, root: JsonValue,
            env: dict[str, JsonValue]) -> Iterator[JsonValue]:
    """Apply basic jq path updates while retaining RHS generator values."""
    if path.kind == "param":
        callback = env.get(path.value)
        if isinstance(callback, tuple) and callback[0] == "filter":
            yield from _update(callback[1], rhs, op, root, callback[2])
            return
    if path.kind == "call":
        function = env.get("__funcs__", {}).get((str(path.value), 0))
        if function is not None:
            values = list(ev(function[1], root, function[2]))
            locations = _paths(function[1], root, function[2])
            if locations:
                path = function[1]
            else:
                displayed = values[0] if len(values) == 1 else values
                raise RuntimeJqError(f"Invalid path expression with result {json.dumps(displayed, separators=(',', ':'))}")
    if path.kind == 'identity':
        old = root
        replacements = list(ev(rhs, old, env))
        if op != '=':
            replacements = [_binary(op[:-1], old, x) if op != '//=' else (old if is_truthy(old) else x) for x in replacements]
        yield from replacements
        return
    if path.kind == 'field' and len(_paths(path, root, env)) <= 1:
